documents.named_driver:
yamaa: "1.0"
type: spec
domain: TEST
keys: [I]
input: {SRC: {path: input.csv, types: {I: int, V: int}}}
intermediates:
  - {id: DRV, dataset: SRC, filter: "SRC.K = 'Y'"}
columns:
  - {name: I, type: int}
  - {name: G, type: str}
  - {name: V, type: int}
rows:
  - id: selected
    dataset: DRV
    derivations:
      I: DRV.I
      G: {str_case: {source: DRV.G, to: lower}}
      V: DRV.V
output: {path: out.csv, columns: [I, G, V]}

documents.key_identity:
yamaa: "1.0"
type: spec
domain: OUT
input: {SRC: {path: input.csv, types: {X: str, Y: str}}}
keys: [B, A]
output: {path: out.csv, columns: [A, B]}
columns:
  - {name: A, type: str, derivation: SRC.X}
  - {name: B, type: str, derivation: SRC.Y}

documents.visits:
yamaa: "1.0"
type: spec
domain: OUT
base: SRC
input: {SRC: {path: input.csv, types: {G: str, X: float, S: int}}}
keys: [GRP, SEQ]
output: {path: out.csv, columns: [GRP, SEQ, VAL, PREV]}
columns:
  - {name: GRP, type: str}
  - {name: SEQ, type: int}
  - {name: VAL, type: float}
  - {name: PREV, type: float}
rows:
  - id: visits
    derivations:
      GRP: SRC.G
      SEQ: SRC.S
      VAL: SRC.X
      PREV: {row_value: {source: VAL, offset: -1, window: {group_by: [GRP], order_by: [SEQ]}}}

documents.window_value:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID, SEQ]
input: {SRC: {path: source.csv, types: {ID: int, VAL: int}}}
output: {path: out.csv, columns: [ID, SEQ, VALUE]}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - name: SEQ
    type: int
    derivation:
      row_number:
        window: {group_by: [ID], order_by: [SRC.VAL]}
  - name: VALUE
    type: str
    derivation: {flag: 'SRC.VAL > 3'}

documents.odm_window:
yamaa: "1.0"
type: spec
domain: OUT
keys: [USUBJID, SEQ]
input: {ODM: odm.csv}
output: {path: out.csv, columns: [USUBJID, SEQ, SEX]}
columns:
  - {name: USUBJID, type: str, derivation: ODM.SubjectKey}
  - name: SEQ
    type: int
    derivation:
      row_number:
        window: {group_by: [USUBJID], order_by: [ODM.ItemGroupRepeatKey]}
  - {name: SEX, type: str, derivation: {odm: ODM.IT.DM.SEX}}

documents.aggregate_key:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID, TOP]
input: {SRC: {path: source.csv, key: [ID], types: {ID: int, VAL: int}}}
output: {path: out.csv, columns: [ID, TOP]}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: TOP, type: int, derivation: {aggregate: 'MAX(SRC.VAL)'}}

documents.odm_key:
yamaa: "1.0"
type: spec
domain: OUT
keys: [USUBJID, SEX]
input: {ODM: odm.csv}
output: {path: out.csv, columns: [USUBJID, SEX]}
columns:
  - {name: USUBJID, type: str, derivation: ODM.SubjectKey}
  - {name: SEX, type: str, derivation: {odm: ODM.IT.DM.SEX}}

documents.non_key:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
input: {SRC: {path: source.csv, types: {ID: int, VAL: int}}}
output: {path: out.csv, columns: [ID, VALUE]}
columns:
  - {name: VALUE, type: int, derivation: SRC.VAL}
  - {name: ID, type: int, derivation: VALUE + 1}

files.spec.yaml:
yamaa: "1.0"
type: spec
domain: TEST
keys: [I]
input: {SRC: input.csv}
columns:
  - {name: I, type: int, derivation: SRC.I}
  - {name: G, type: str, derivation: SRC.G}
  - {name: F, type: str, derivation: SRC.F}
  - {name: B, type: str, derivation: SRC.B}
output: {path: out.csv, columns: [I, G, F, B], report: checks.csv}
verifications:
  - row_count: {group_by: [G], filter: "F = 'Y'", when: "B = 'Y'", min_fraction: 0.5, max_fraction: 0.5}

edits.to:
- {name: A, type: int, derivation: SRC.X}
- {name: B, type: str, derivation: SRC.Y}
- {name: VALUE, type: str, derivation: SRC.Z}

- {name: A, type: int, derivation: SRC.X}
- {name: B, type: str, derivation: SRC.Y}
- {name: VALUE, type: str, derivation: SRC.Z}

- {name: PREV, type: float}
- {name: CHG, type: float}
- {name: DOUBLED, type: float}

PREV: {row_value: {source: VAL, offset: -1, window: {group_by: [GRP], order_by: [SEQ]}}}
DOUBLED: 'CHG * 2'
CHG: 'VAL - PREV'

- {name: PREV, type: float}
- {name: DOUBLED, type: float}
- {name: BAD, type: float}

PREV: {row_value: {source: VAL, offset: -1, window: {group_by: [GRP], order_by: [SEQ]}}}
DOUBLED: 'PREV * 2'
BAD: {row_value: {source: DOUBLED, offset: -1, window: {group_by: [GRP], order_by: [SEQ]}}}
